static int integerfile(const char *file,long long *value){char data[128];if(!readtext(file,data,sizeof data))return 0;char *end;errno=0;*value=strtoll(data,&end,10);return end!=data&&!errno;}
static int externalpower(void){long long value;const char *files[]={"/sys/class/power_supply/usb/online","/sys/class/power_supply/ac/online","/sys/class/power_supply/wireless/online"};for(int i=0;i<3;i++)if(integerfile(files[i],&value)&&value==1)return 1;return 0;}
static void live(double elapsed){char file[512],temp[512],text[64];FrameLayer *best=NULL;for(int i=0;i<frames.nlayers;i++){FrameLayer *l=&frames.layers[i];if(l->presented&&(!best||l->last>best->last))best=l;}int bin=(int)elapsed-2;double fps=best&&bin>=0&&bin<=600?best->bins[bin]:-1;long long current,voltage,battery;int havePower=integerfile("/sys/class/power_supply/battery/current_now",&current)&&integerfile("/sys/class/power_supply/battery/voltage_now",&voltage)&&current>=-20000000&&current<=20000000&&voltage>=1000000&&voltage<=6000000,haveTemp=integerfile("/sys/class/power_supply/battery/temp",&battery)&&battery>=-500&&battery<=1000;int charging=readtext("/sys/class/power_supply/battery/status",text,sizeof text)?(!strncmp(text,"Charging",8)||!strncmp(text,"Full",4)?1:0):-1;if(externalpower())charging=1;path(file,sizeof file,"record.live.tsv");path(temp,sizeof temp,"record.live.tmp");FILE *f=fopen(temp,"w");if(f){double power=havePower?(current<0?-current:current)*(double)voltage/1e12:-1;fprintf(f,"%s\t%.0f\t%.1f\t%ld\t%ld\t%ld\t%ld\t%.3f\t%.1f\t%d\n",frames.selection,elapsed*1000,fps,numeric("/sys/devices/system/cpu/cpufreq/policy0/scaling_cur_freq"),numeric("/sys/devices/system/cpu/cpufreq/policy4/scaling_cur_freq"),numeric("/sys/devices/system/cpu/cpufreq/policy7/scaling_cur_freq"),gpucurrent(),power,haveTemp?battery/10.0:-999,charging);fclose(f);rename(temp,file);}}
static void metrics(FILE *file,double elapsed){long long current=0,voltage=0,temp=0,gpu=0;int haveCurrent=integerfile("/sys/class/power_supply/battery/current_now",&current)&&current>=-20000000&&current<=20000000,haveVoltage=integerfile("/sys/class/power_supply/battery/voltage_now",&voltage)&&voltage>=1000000&&voltage<=6000000,haveTemp=integerfile("/sys/class/power_supply/battery/temp",&temp)&&temp>=-500&&temp<=1000,haveGpu=integerfile("/sys/kernel/ged/hal/gpu_utilization",&gpu)&&gpu>=0&&gpu<=100;char state[64];int charging=readtext("/sys/class/power_supply/battery/status",state,sizeof state)?(!strncmp(state,"Charging",8)||!strncmp(state,"Full",4)?1:!strncmp(state,"Discharging",11)||!strncmp(state,"Not charging",12)?0:-1):-1;if(externalpower())charging=1;fprintf(file,"%.0f,",elapsed*1000);if(haveCurrent)fprintf(file,"%lld",current);fputc(',',file);if(haveVoltage)fprintf(file,"%lld",voltage);fputc(',',file);if(haveTemp)fprintf(file,"%lld",temp);fprintf(file,",%d,",charging);if(haveGpu)fprintf(file,"%lld",gpu);fputc('\n',file);fflush(file);}
